mapper.select:
select co.offering_id, co.semester_id, co.course_id, co.teacher_id, co.campus_id, co.class_count, co.max_students,
       co.offering_status, co.status, co.del_flag, co.create_by, co.create_time, co.update_by, co.update_time, co.remark,
       se.semester_name as semester_name,
       cl.course_name as course_name,
       cl.course_code as course_code,
       t.teacher_name as teacher_name,
       ca.campus_name as campus_name
from tpm_course_offering co
left join brm_semester se on co.semester_id = se.semester_id
left join tpm_course_library cl on co.course_id = cl.course_id
left join brm_teacher t on co.teacher_id = t.teacher_id
left join sys_dept d on t.dept_id = d.dept_id
left join brm_campus ca on co.campus_id = ca.campus_id

    co.del_flag = '0'
     and co.semester_id = #{semesterId}
     and co.course_id = #{courseId}
     and co.teacher_id = #{teacherId}
     and co.campus_id = #{campusId}
     and co.offering_status = #{offeringStatus}
     and co.status = #{status}

    ${params.dataScope}

mapper.update:
update tpm_course_offering
semester_id = #{semesterId}, course_id = #{courseId}, teacher_id = #{teacherId}, campus_id = #{campusId}, class_count = #{classCount}, max_students = #{maxStudents}, offering_status = #{offeringStatus}, status = #{status}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where offering_id = #{offeringId}
